function taskBadge(t){return badge(t.status,t.status==='已完成'?'green':t.status==='等待反馈'?'orange':t.status==='阻塞'?'red':t.status==='进行中'?'blue':'');}
function sourceIcon(t){return `<span class="source-icon ${t.source}" aria-hidden="true">${t.source==='pc'?'P':t.source==='gl'?icon('git'):icon('file')}</span>`;}
function toast(message){state.lastAction=message;const el=$('#toast');el.textContent=message;el.classList.add('toast-show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('toast-show'),3500);if(state.showState)renderState();}
function urlUpdate(){const q=new URLSearchParams(location.search);q.set('variant',state.variant);if(state.view==='today')q.delete('view');else q.set('view',state.view);history.replaceState({},'',`${location.pathname}?${q}`);}
function confirmPromptDiscard(){if(!state.promptDirty)return true;const discard=confirm('提示词有未保存的修改。离开后将放弃这些修改，是否继续？');if(discard){if(state.prompts[state.selectedPrompt]?.updated==='尚未保存'){state.prompts.splice(state.selectedPrompt,1);state.selectedPrompt=Math.max(0,state.selectedPrompt-1);}state.promptDirty=false;state.promptDraft=null;}return discard;}
function navigate(view){if(state.view==='prompts'&&!confirmPromptDiscard())return;state.promptDirty=false;state.promptDraft=null;state.view=view;closeOverlay();urlUpdate();render();window.scrollTo(0,0);}
function changeVariant(v){state.variant=v;urlUpdate();render();toast(`方案 ${v} · ${ {A:'今日驾驶舱',B:'行动清单',C:'周计划板'}[v] }`);}
function cycleVariant(direction){const vs=['A','B','C'];changeVariant(vs[(vs.indexOf(state.variant)+direction+3)%3]);}
function brand(){return `<div class="brand"><div class="brand-mark">${icon('tasks')}</div><div class="brand-name">序<small>PERSONAL WORKSPACE</small></div></div>`;}
function navItem(n){const count=n[0]==='tasks'?personal().filter(t=>t.status!=='已完成').length:n[0]==='prompts'?state.prompts.length:'';return `<button class="nav-item ${state.view===n[0]?'active':''}" data-nav="${n[0]}" aria-label="${n[2]}" title="${n[2]}" ${state.view===n[0]?'aria-current="page"':''}>${icon(n[1])}<span>${n[2]}</span>${count!==''?`<span class="nav-count">${count}</span>`:''}</button>`;}
function sidebar(){return `<aside class="sidebar">${brand()}<div class="nav-group">我的工作空间</div>${navs.slice(0,4).map(navItem).join('')}<div class="nav-group">工具与资料</div>${navs.slice(4,6).map(navItem).join('')}<div class="sidebar-bottom"><div class="connection-note"><div class="row">${icon('shield')}<span>专注当下，有序推进</span></div><p>个人安排与来源状态各自保留<br>所有内容均为虚构演示</p></div>${navItem(navs[6])}<div class="profile row"><span class="avatar teal">我</span><div class="grow"><strong>我的工作空间</strong><br><small>本次原型 · 单用户</small></div>${icon('down')}</div></div></aside>`;}
function topbar(){return `<header class="topbar"><div class="breadcrumb">我的工作空间 <span class="muted"> / </span><b>${navs.find(n=>n[0]===state.view)[2]}</b></div><div class="top-actions"><label class="global-search">${icon('search')}<input id="global-search" placeholder="搜索任务、编号…" aria-label="全局搜索任务"><kbd>Ctrl K</kbd></label><span class="top-separator"></span><span class="demo-tag">交互原型 · 虚构数据</span><button class="icon-btn" data-action="followups" aria-label="查看待跟进事项">${icon('bell')}</button><span class="avatar teal">我</span></div></header>`;}
function switcher(){return `<div class="prototype-switcher" aria-label="原型布局切换"><span class="prototype-label">PROTOTYPE</span><span class="divider"></span><button class="icon-btn" data-action="variant-prev" aria-label="上一种布局">${icon('left')}</button>${[['A','驾驶舱'],['B','行动清单'],['C','周计划板']].map(([v,l])=>`<button class="variant-pill ${state.variant===v?'active':''}" data-variant="${v}" aria-pressed="${state.variant===v}">${v} · ${l}</button>`).join('')}<button class="icon-btn" data-action="variant-next" aria-label="下一种布局">${icon('chevron')}</button><span class="divider"></span><button class="icon-btn" data-action="state" aria-label="查看原型状态">${icon('info')}</button></div>${state.showState?'<aside class="state-popover" id="state-popover"></aside>':''}`;}
function demoNote(){return `<p class="demo-note">${icon('info')}演示日期固定为 2026年11月06日 · Asia/Shanghai · 业务数据仅保留在本次打开期间</p>`;}
function render(){
 document.title=`${navs.find(n=>n[0]===state.view)[2]} · 序 — 原型 ${state.variant}`;
 const content=page();
 if(state.variant==='B')$('#app').innerHTML=`<div class="b-shell"><header class="b-header">${brand()}<nav class="b-nav" aria-label="主导航">${navs.map(n=>`<button data-nav="${n[0]}" class="${state.view===n[0]?'active':''}">${n[2]}</button>`).join('')}</nav><span class="demo-tag">交互原型 · 虚构数据</span></header><main class="b-body">${content}${demoNote()}</main>${switcher()}</div>`;
 else if(state.variant==='C')$('#app').innerHTML=`<div class="c-shell"><nav class="c-rail" aria-label="主导航"><div class="brand-mark">${icon('tasks')}</div>${navs.map(n=>`<button data-nav="${n[0]}" class="${state.view===n[0]?'active':''}" aria-label="${n[2]}" title="${n[2]}">${icon(n[1])}</button>`).join('')}<span style="flex:1"></span><span class="avatar teal">我</span></nav><div class="c-main">${topbar()}<main class="content">${content}${demoNote()}</main></div>${switcher()}</div>`;
 else $('#app').innerHTML=`<div class="shell">${sidebar()}<div class="main-shell">${topbar()}<main class="content">${content}${demoNote()}</main></div>${switcher()}</div>`;
 if(state.showState)renderState();
}
function renderState(){const el=$('#state-popover');if(!el)return;el.innerHTML=`<div class="row between"><strong>当前原型状态</strong><button data-action="state" class="icon-btn" aria-label="关闭原型状态">${icon('close')}</button></div><pre>${esc(JSON.stringify({布局:state.variant,页面:state.view,今日重点:todayTasks().map(t=>t.ref),个人行动完成:personal().filter(t=>t.status==='已完成').map(t=>t.ref),待复查:pendingMR().map(t=>t.ref),提示词未保存:state.promptDirty,同步暂停:state.syncPaused,最近操作:state.lastAction,外部系统:'未连接',持久保存:false},null,2))}</pre>`;}
function heading(title,sub,actions='',eyebrow='MY WORKSPACE'){return `<div class="page-heading"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1>${sub?`<p class="page-subtitle">${sub}</p>`:''}</div><div class="heading-actions">${actions}</div></div>`;}
function page(){return ({today:todayPage,tasks:tasksPage,manage:managePage,prompts:promptsPage,review:reviewPage,executions:executionsPage,settings:settingsPage})[state.view]();}
function syncStrip(){return `<div class="sync-strip"><div class="row"><span class="sync-item"><i class="dot"></i>PingCode <span>${esc(state.sync.pc)}</span></span><span class="sync-item ${state.sync.gl.includes('失败')?'warning':''}"><i class="dot"></i>GitLab <span>${esc(state.sync.gl)}</span></span></div><button class="text-link" data-action="sync-info">${icon('refresh')}同步详情</button></div>`;}
function metrics(){const items=[['flag','今日重点',todayTasks().filter(t=>t.status!=='已完成').length,'按个人计划推进','个人安排，与来源截止独立'],['clock','等待与跟进',state.tasks.filter(t=>t.status==='等待反馈').length,'项待反馈','需要反馈的事项集中跟进'],['git','MR 待复查',pendingMR().length,'个新版本','保留原结论，重新核对版本'],['layers','产线需关注',lines.filter(l=>l.tone!=='green').length,'条产线','偏差与反馈缺失优先可见']];return `<div class="metric-strip">${items.map(([i,l,n,s,f])=>`<div class="metric"><div class="metric-label">${icon(i)}${l}</div><div class="metric-number">${String(n).padStart(2,'0')}<span>${s}</span></div><div class="metric-foot">${f}</div></div>`).join('')}</div>`;}
function taskRow(t){return `<div class="task-row" data-task-row="${t.id}"><button class="task-check ${t.status==='已完成'?'done':''}" data-toggle-task="${t.id}" aria-label="${t.status==='已完成'?'重开':'完成'}个人行动：${esc(t.title)}">${t.status==='已完成'?icon('check'):''}</button><div class="grow"><button class="task-title ${t.status==='已完成'?'done':''}" data-task="${t.id}">${esc(t.title)}</button><div class="task-meta">${badge(t.type,t.source==='gl'?'purple':t.type==='Bug'?'red':'')}<span>${esc(t.ref)}</span><span>·</span><span>${esc(t.project)}</span>${t.source==='gl'&&t.current!==t.checked?badge('新提交','orange'):''}</div><div class="task-next">${esc(t.next)}</div></div><div class="task-right">${taskBadge(t)}<span class="avatar ${t.source==='gl'?'lilac':'teal'}">我</span></div></div>`;}
function lineItem(l){const feedback=state.feedback[l.id];return `<div class="line-item"><div class="row between"><div class="row"><span class="line-color ${l.color}"></span><span class="line-label">${l.name}</span></div>${badge(l.badge,l.tone)}</div><p class="line-summary">${esc(feedback||l.actual)}</p><div class="row between"><span class="line-step"><span class="filled"></span><span class="filled"></span><span class="${l.tone==='orange'?'warn':''}"></span><span></span> ${l.stage}</span><button class="text-link" data-line="${l.id}">详情 ${icon('chevron')}</button></div></div>`;}
function followups(){return `<div class="panel pad"><div class="section-head"><h2>等待与跟进 <span class="count">3</span></h2><span class="muted" style="font-size:10px">演示日待处理</span></div><div class="follow-row"><div class="date-block"><small>今天</small>15:00</div><div class="grow"><button class="task-title" data-task="pc2">确认接口异常码约定</button><p>等待负责人乙 · 产线 B</p></div>${badge('待反馈','orange')}</div><div class="follow-row"><div class="date-block"><small>今天</small>16:00</div><div class="grow"><button class="task-title" data-task="mg2">收集中心本周总结材料</button><p>仍缺验收依据 · 等待补充</p></div></div><div class="follow-row"><div class="date-block"><small>11月</small>09</div><div class="grow"><button class="task-title" data-task="gl3">跟进 MR !92 的修改</button><p>等待作者补充幂等说明</p></div></div></div>`;}
function todayPage(){if(state.variant==='B')return todayB();if(state.variant==='C')return todayC();const focus=todayTasks().find(t=>t.id===state.focusId&&t.status!=='已完成')||todayTasks().find(t=>t.status!=='已完成');return `${heading('把重要的事，向前推进。','个人任务有下一步，产线进展有着落。',button('周回顾','review','','review')+button('快速记录','quick-add','primary','plus'),'FRIDAY, NOVEMBER 06 · 演示日')}${syncStrip()}${metrics()}<div class="today-flow"><div class="section-head"><h2>今日重点 <span class="count">${todayTasks().length}</span></h2><button class="text-link" data-action="all-tasks">管理今日安排 ${icon('arrow')}</button></div>${focus?`<div class="focus-card"><div class="focus-top row">${icon('sun')} 当前专注 · ${esc(focus.ref)}</div><h3>${esc(focus.title)}</h3><p>${esc(focus.next)}</p><div class="row">${button('查看任务',`task:${focus.id}`,'primary','arrow')}${button('AI 帮我拆解',`split:${focus.id}`,'ghost','spark')}</div><div class="focus-bottom"><span>${esc(focus.validation)}</span><span class="focus-spark" aria-hidden="true">${Array(7).fill('<i style="height:8px"></i>').join('')}</span></div></div>`:`<div class="focus-card"><div class="focus-top row">${icon('check')} 当前专注</div><h3>今日没有未完成的重点行动。</h3><p>可以安排下一件事，或整理已有进展。</p>${button('安排今日任务','all-tasks','primary','plus')}</div>`}<div class="task-list today-task-list">${todayTasks().map(taskRow).join('')}</div></div><div class="today-secondary"><section class="today-longterm"><div class="section-head"><h2>长期事项，也向前一小步</h2>${badge('AI 基建')}</div><div class="panel milestone"><span class="milestone-number">01</span><div class="grow"><h3>从“环境部署完成”到“实际效果验证”</h3><p>用脱敏问题完成首次试用，保留检索结果与人工评价。</p></div><button class="icon-btn" data-task="pc3" aria-label="查看知识检索试用任务">${icon('arrow')}</button></div></section>${followups()}<div class="review-banner">${icon('spark')}<div class="grow"><h3>让本周的进展，成为有依据的总结</h3><p>选择事实材料，生成可编辑的回顾草稿。</p></div><button class="icon-btn" data-nav="review" aria-label="进入本周回顾">${icon('arrow')}</button></div></div><section class="panel today-lines"><div style="padding:20px 20px 3px"><div class="section-head"><h2>产线本周</h2><button class="text-link" data-nav="manage">管理概览 ${icon('chevron')}</button></div></div><div class="today-lines-grid">${lines.map(lineItem).join('')}</div><div class="panel-foot">${icon('clock')}周范围 11月02日—11月08日 · 阶段示意</div></section>`;}
function todayB(){return `<div class="page-heading"><div class="row" style="gap:24px"><div class="b-date">06<small style="font-size:10px;display:block;letter-spacing:2px;margin-top:7px">NOV / FRI</small></div><div><div class="b-kicker">LESS NOISE, MORE PROGRESS</div><h1>今天，专注几件重要的事。</h1><p class="page-subtitle">让行动在左，等待在中，变化在右。</p></div></div><div class="heading-actions">${button('写下新事项','quick-add','dark','plus')}</div></div>${syncStrip()}<div class="b-grid"><section class="b-column"><div class="section-head"><h2>01 / 今日行动</h2><span class="muted">${todayTasks().filter(t=>t.status!=='等待反馈').length} 项</span></div><p class="b-note">完成的是个人行动，来源交付另行核对。</p><div class="task-list">${todayTasks().filter(t=>t.status!=='等待反馈').map(taskRow).join('')}</div>${button('安排更多任务','all-tasks','ghost','plus')}</section><section class="b-column"><div class="section-head"><h2>02 / 等待与阻塞</h2>${badge('需要跟进','orange')}</div><p class="b-note">等待谁、等待什么、什么时候再跟进。</p><div class="task-list">${state.tasks.filter(t=>t.status==='等待反馈'&&!t.sensitive).map(taskRow).join('')}</div></section><section class="b-column"><div class="section-head"><h2>03 / 新变化</h2>${badge('MR 复查','purple')}</div><p class="b-note">旧版本结论保留，新版本重新检查。</p><div class="task-list">${pendingMR().map(taskRow).join('')}</div><div class="notice" style="margin-top:20px">产线 A 回归窗口尚未确定，需要协调测试资源。<br><button class="text-link" data-task="mg1">查看协调行动 ${icon('arrow')}</button></div></section></div><div class="section-head" style="margin-top:36px"><h2>三条产线，本周需要知道的</h2><button class="text-link" data-nav="manage">完整管理视图 ${icon('arrow')}</button></div><div class="b-bottom" style="margin-top:0">${lines.map(lineItem).join('')}</div><div class="review-banner" style="margin-top:28px">${icon('review')}<div class="grow"><h3>这一周，哪些事情有了进展？</h3><p>事实、偏差、下周计划，整理成一份可追溯的回顾。</p></div>${button('开始回顾','review','ghost','arrow')}</div>`;}
function dayTask(title,ref,type,task='',past=false){return `<button class="day-task ${past?'past':''}" ${task?`data-task="${task}"`:'data-action="sample-past"'}>${badge(type,type.includes('验证')?'orange':'')}<span class="task-title">${esc(title)}</span><small>${esc(ref)}</small></button>`;}
function todayC(){return `${heading('让这一周，有序向前。','先看一周的承诺，再决定今天的行动。',button('回顾本周','review','','review')+button('新建事项','quick-add','primary','plus'),'WEEK 45 / NOVEMBER 2026 · 演示周期')}<div class="c-week-top"><div><h2>本周行动</h2><p>11月02日—11月08日 · 工作日视图 · 按个人计划日期安排</p></div><div class="row">${badge(`${todayTasks().length} 项今日安排`,'green')}${badge(`${pendingMR().length} 项待复查`,'orange')}<button class="icon-btn" data-action="sync-info" aria-label="同步详情">${icon('refresh')}</button></div></div><div class="week-board"><section class="day-column"><div class="day-header"><span>周一</span><b>02</b></div>${dayTask('梳理异常恢复场景','历史示例 · 个人行动已完成','已完成','',true)}${dayTask('收集三产线月重点','历史示例 · 月交付未验收','已记录','',true)}</section><section class="day-column"><div class="day-header"><span>周二</span><b>03</b></div>${dayTask('完成接口草案初稿','历史示例 · 初稿待确认','草案','',true)}${state.tasks.filter(t=>!t.management&&t.day===1).map(t=>dayTask(t.title,t.ref,t.status,t.id)).join('')}</section><section class="day-column"><div class="day-header"><span>周三</span><b>04</b></div>${state.tasks.filter(t=>!t.management&&t.day===2).map(t=>dayTask(t.title,t.ref,t.review||t.status,t.id)).join('')}</section><section class="day-column"><div class="day-header"><span>周四</span><b>05</b></div>${state.tasks.filter(t=>!t.management&&t.day===3).map(t=>dayTask(t.title,t.ref,t.review||t.status,t.id)).join('')}</section><section class="day-column current"><div class="day-header"><span>周五 · 演示日</span><b>06</b></div>${state.tasks.filter(t=>!t.management&&t.day===4&&t.today).map(t=>dayTask(t.title,t.ref,t.review||t.status,t.id)).join('')}<button class="day-add" data-action="quick-add">＋ 记录新事项</button></section></div><div class="section-head" style="margin-top:29px"><h2>产线承诺与关键偏差</h2><button class="text-link" data-nav="manage">查看月周关联 ${icon('arrow')}</button></div><div class="c-bottom-grid">${lines.map(l=>`<section class="c-line"><div class="row between"><h3>${l.name}</h3>${badge(l.badge,l.tone)}</div><p>${esc(state.feedback[l.id]||l.actual)}</p><div class="row between"><span class="line-step"><span class="filled"></span><span class="filled"></span><span></span> 周阶段结果</span><button class="text-link" data-line="${l.id}">查看 ${icon('chevron')}</button></div></section>`).join('')}</div><p class="footer-caption">计划安排 ≠ 来源截止 · 阶段结果 ≠ 最终交付</p>`;}
function tasksPage(){let tasks=personal().filter(t=>{
 if(state.taskTab==='today'&&!t.today)return false;if(state.taskTab==='inbox'&&t.status!=='收件箱')return false;if(state.taskTab==='mr'&&t.source!=='gl')return false;
 if(state.source!=='all'&&t.source!==state.source)return false;if(state.type!=='all'&&t.type!==state.type)return false;if(state.project!=='all'&&t.project!==state.project)return false;if(state.taskTab==='mr'&&state.mrFilter!=='all'&&t.review!==state.mrFilter)return false;if(state.taskTab==='mr'&&state.author!=='all'&&t.author!==state.author)return false;
 return `${t.title} ${t.ref} ${t.project} ${t.next}`.toLowerCase().includes(state.taskQuery.toLowerCase());
 });return `${heading('个人任务','来源信息、个人安排与验证结果，各有清楚的位置。',button('刷新来源','sync','','refresh')+button('快速记录','quick-add','primary','plus'),'PERSONAL TASKS')}${syncStrip()}<div class="tabs" role="tablist">${[['all','全部任务',personal().length],['today','今日重点',todayTasks().length],['inbox','收件箱',personal().filter(t=>t.status==='收件箱').length],['mr','MR 评审',personal().filter(t=>t.source==='gl').length]].map(([v,l,c])=>`<button role="tab" aria-selected="${state.taskTab===v}" class="tab ${state.taskTab===v?'active':''}" data-task-tab="${v}">${l}${badge(c)}</button>`).join('')}</div><div class="filter-row"><input class="input filter-search" id="task-search" placeholder="搜索任务标题、来源编号…" value="${esc(state.taskQuery)}" aria-label="搜索任务">${select('source-filter',[['all','全部来源'],['pc','PingCode'],['gl','GitLab'],['local','本地']],state.source,'筛选来源')}${select('project-filter',[['all','全部项目'],...Array.from(new Set(personal().map(t=>t.project))).map(p=>[p,p])],state.project,'筛选项目')}${state.taskTab==='mr'?select('mr-filter',[['all','全部评审进展'],...['待审','评审中','等待修改','待复查','已结束'].map(x=>[x,x])],state.mrFilter,'筛选评审进展')+select('author-filter',[['all','全部作者'],['同事甲','同事甲'],['同事乙','同事乙']],state.author,'筛选作者'):select('type-filter',[['all','全部类型'],...['Bug','功能','平台提效','MR 评审','临时事项'].map(x=>[x,x])],state.type,'筛选类型')}<span class="grow"></span><small class="muted">${tasks.length} 项</small></div>${state.taskTab==='mr'?'<div class="notice" style="margin-bottom:18px">GitLab 只读 · 外部状态、本人评审进展与已检查版本分别展示。新提交需复查；已合并仍可能有遗留行动。</div>':''}<div class="panel table-wrap"><table class="task-table"><thead><tr><th>来源 / 编号</th><th>任务与下一步</th><th>${state.taskTab==='mr'?'本人评审进展':'个人行动'}</th><th>来源状态</th><th>${state.taskTab==='mr'?'提交版本':'个人计划'}</th><th>${state.taskTab==='mr'?'作者':'验证情况'}</th></tr></thead><tbody>${tasks.map(t=>`<tr data-task="${t.id}" tabindex="0" role="button" aria-label="查看 ${esc(t.title)}"><td><div class="row">${sourceIcon(t)}<div>${esc(t.ref)}<div class="task-next">${esc(t.project)}</div></div></div></td><td class="title-cell"><strong style="font-weight:500">${esc(t.title)}</strong><div class="task-next">${esc(t.next)}</div></td><td>${state.taskTab==='mr'?badge(t.review,t.review==='待复查'?'orange':'purple'):taskBadge(t)}</td><td>${badge(t.original)}</td><td>${state.taskTab==='mr'?`<code>${t.current}</code><div class="task-next">已检查 ${t.checked}</div>`:t.today?'今日重点':t.plan==='tomorrow'?'明日 · 11月07日':'未安排'}</td><td style="font-size:10px;color:var(--muted)">${state.taskTab==='mr'?esc(t.author):esc(t.validation)}</td></tr>`).join('')}</tbody></table>${!tasks.length?'<div class="empty">没有符合条件的任务<br>可以调整筛选，或记下一件新事项。</div>':''}</div>`;}
function select(id,options,value,label){return `<select id="${id}" aria-label="${label}">${options.map(([v,l])=>`<option value="${esc(v)}" ${v===value?'selected':''}>${esc(l)}</option>`).join('')}</select>`;}
function managePage(){return `${heading('管理','围绕月目标，跟进周结果；把需要介入的偏差放在眼前。',button('记录事项','quick-add','','plus'),'MANAGEMENT')}<div class="tabs"><button class="tab ${state.manageTab==='line'?'active':''}" data-manage-tab="line">产线管理${badge('3')}</button><button class="tab ${state.manageTab==='other'?'active':''}" data-manage-tab="other">其他管理事项${badge(state.tasks.filter(t=>t.management).length)}</button></div>${state.manageTab==='other'?`<div class="notice" style="margin-bottom:18px">人员、招聘、交办与周期总结共用轻量任务。敏感事项默认不进入回顾与普通导出。</div><div class="task-list">${state.tasks.filter(t=>t.management&&!t.sensitive).map(taskRow).join('')}<div class="task-row"><div class="sensitive grow">${icon('shield')} 人员沟通跟进 · 敏感事项正文已隐藏 · 下次跟进 11月09日</div><button class="text-link" data-task="mg3">查看</button></div></div>`:`<div class="row between" style="margin-bottom:22px"><div class="row">${button('周重点','cycle-week',state.cycle==='week'?'primary':'')}${button('月重点','cycle-month',state.cycle==='month'?'primary':'')}</div><div class="date-range">${icon('calendar')} ${state.cycle==='week'?'11月02日—11月08日':'2026年11月'}</div></div><div class="management-grid">${lines.map(l=>`<section class="panel line-card"><div class="row between"><div class="row"><span class="line-color ${l.color}"></span><h3>${l.name}</h3></div>${badge(l.badge,l.tone)}</div><span class="muted" style="font-size:10px">${l.owner} · ${state.cycle==='week'?'本周预期阶段结果':'本月预期交付'}</span><div class="objective">${state.cycle==='week'?l.week:l.month}</div><div class="label">${state.cycle==='week'?'关联月目标':'关联周重点'}</div><p>${state.cycle==='week'?l.month:l.week}</p><div class="result-block"><strong>实际进展</strong><p>${esc(state.feedback[l.id]||l.actual)}${l.task?`<br><button class="text-link" data-task="${l.task}">关联任务 ${findTask(l.task).ref} ${icon('link')}</button>`:''}</p></div><div class="label">计划节点 / 反馈时间</div><p>${state.cycle==='week'?'11月06日':'11月30日'} / ${state.feedback[l.id]?'11月06日 · 本次演示记录':l.feedback}</p><div class="actions"><button class="btn small" data-feedback="${l.id}">${icon('edit')}记录反馈</button><button class="btn small ghost" data-carry="${l.id}">调整 / 结转 ${icon('arrow')}</button></div></section>`).join('')}</div><div class="notice" style="margin-top:20px">周阶段任务完成后，月目标仍须按交付标准核验。完成本人协调行动后，产线风险继续保留，等待处置依据。</div><div class="risk-table"><div class="section-head"><h2>关键风险与本人协调</h2><span class="muted" style="font-size:10px">2 项需关注</span></div><div class="panel table-wrap"><table class="task-table"><thead><tr><th>关联产线</th><th>风险 / 偏差</th><th>影响与应对</th><th>复查日期</th><th>本人行动</th></tr></thead><tbody><tr data-task="mg1" tabindex="0" role="button"><td>${badge('产线 A','orange')}</td><td>测试资源冲突 ${badge('开放','orange')}</td><td>回归窗口可能后移；确认替代资源</td><td>11月06日</td><td>协调测试资源 ${icon('chevron')}</td></tr><tr data-line="C" tabindex="0" role="button"><td>${badge('产线 C','purple')}</td><td>反馈缺失 ${badge('待确认','purple')}</td><td>无法判断稳定性结果；补齐验证依据</td><td>11月06日</td><td>跟进负责人反馈 ${icon('chevron')}</td></tr></tbody></table></div></div>${state.carried.length?`<div class="notice green" style="margin-top:18px">${state.carried.map(c=>`${esc(c.line)} 已结转至 ${esc(c.period)}。原周期保持未完成；原因：${esc(c.reason)}`).join('<br>')}</div>`:''}`}`;}
function promptsPage(){const p=state.promptDraft||state.prompts[state.selectedPrompt];return `${heading('提示词库','把常用的好指令留下来，下次直接复制。',button('新建提示词','new-prompt','primary','plus'),'PROMPT LIBRARY')}<div class="prompt-layout"><aside class="panel"><div style="padding:16px 14px 6px"><input class="input" id="prompt-search" placeholder="搜索标题或正文…" value="${esc(state.promptQuery)}" aria-label="搜索提示词"></div><div class="prompt-menu">${state.prompts.map((p,i)=>({p,i})).filter(({p})=>(p.title+p.body).includes(state.promptQuery)).map(({p,i})=>`<button class="prompt-card ${i===state.selectedPrompt?'active':''}" data-prompt="${i}"><h3>${esc(p.title)}</h3><p>${esc(p.tag)} · ${esc(p.updated)}</p></button>`).join('')||'<div class="empty">没有匹配的提示词</div>'}</div></aside><section class="panel prompt-editor"><div class="editor-toolbar"><div class="row">${icon('prompt')}${badge(p.tag||'未分类','green')}<span id="prompt-save-state" class="muted" style="font-size:10px">${state.promptDirty?'有未保存修改':'本次演示 · 已保存正文'}</span></div>${button('保存','save-prompt','primary small','check')}</div><label class="field"><span>标题</span><input class="input" id="prompt-title" value="${esc(p.title)}" placeholder="给提示词起个名字"></label><label class="field"><span>用途 / 标签</span><input class="input" id="prompt-tag" value="${esc(p.tag)}" placeholder="例如：研发排障"></label><label class="field"><span>提示词正文 · 保留缩进、换行及占位符</span><textarea class="input" id="prompt-body" spellcheck="false">${esc(p.body)}</textarea></label><div class="row between"><small class="muted" id="prompt-char-count">${p.body.length} 个字符 · 复制使用最近保存的正文</small><div class="row">${button('填入 AI 指令','use-prompt','','spark')}${button('复制正文','copy-prompt','primary','copy')}</div></div><div class="notice" style="margin-top:20px">这是原型中的临时保存，刷新页面会重置。正式产品须验证关闭重开和备份恢复后的内容保留；本原型不代表该能力已验收。</div></section></div>`;}
function sourceMaterial(){const taskMaterials=state.tasks.filter(t=>!t.sensitive&&t.status!=='已取消').filter(t=>state.reviewPeriod==='month'||['pc1','pc2','gl1'].includes(t.id));return [...taskMaterials.map(t=>({id:t.id,title:t.title,ref:t.ref,note:`${t.management?'管理行动':t.source==='gl'?'评审行动':'个人行动'} · ${t.validation}`})),...lines.filter(l=>state.reviewPeriod==='month'||l.id!=='C').map(l=>({id:`line${l.id}`,title:`${l.name} · ${state.reviewPeriod==='week'?'周阶段反馈':'月目标进展'}`,ref:`${l.name} / 2026-11`,note:l.actual}))];}
function reviewPage(){const mats=sourceMaterial();return `${heading('给进展，一份有依据的回顾。','选事实、看偏差、定下一步。草稿由你复核后再使用。',button('导出 Markdown','export-review','','download'),'REFLECT & PLAN')}<div class="row between" style="margin-bottom:23px"><div class="row">${button('周回顾','review-week',state.reviewPeriod==='week'?'primary':'')}${button('月回顾','review-month',state.reviewPeriod==='month'?'primary':'')}</div><span class="date-range">${icon('calendar')}${state.reviewPeriod==='week'?'11月02日—11月08日':'2026年11月01日—11月30日'}</span></div><div class="review-layout"><section class="panel pad"><div class="section-head"><h2>选择事实材料</h2><span id="review-count" class="muted" style="font-size:10px">${mats.filter(m=>state.reviewSources.has(m.id)).length} 项已选</span></div>${mats.map(m=>`<label class="source-choice"><input type="checkbox" data-review-source="${m.id}" ${state.reviewSources.has(m.id)?'checked':''}><span><h4>${esc(m.title)}</h4><p>${esc(m.ref)}<br>${esc(m.note)}</p></span></label>`).join('')}<div class="sensitive" style="margin-top:14px">${icon('shield')}人员与候选人敏感材料默认排除</div></section><section class="panel prompt-editor"><div class="row between" style="margin-bottom:18px"><h2>回顾草稿</h2>${badge('需人工复核','orange')}</div><div class="row between" style="margin-bottom:15px"><small class="muted">模型：演示本地模型 · 未实际调用</small>${button('生成演示草稿','generate-review','small','spark')}</div><textarea class="input review-draft" id="review-draft" placeholder="选择左侧事实材料，再生成演示草稿；也可直接手工整理。">${esc(state.reviewText)}</textarea><div class="row between" style="margin-top:15px"><span class="muted" style="font-size:10px">保留来源编号 · 普通总结不含敏感正文</span>${button('复制草稿','copy-review','small','copy')}</div><div class="notice" style="margin-top:18px">中心材料尚不完整，不能将个人台账视为完整中心总结。AI 建议和未核实反馈不计为已验收成果。</div></section></div>`;}
const executionSteps=['读取选定材料','按来源整理事实与偏差','生成草稿产物','核对来源与产物'];
function executionsPage(){const ex=state.executions[state.selectedExecution];return `${heading('AI 执行记录','计划、授权、操作和核验结果，放在同一条记录里。',button('新建执行','new-execution','primary','plus'),'AI EXECUTIONS')}<div class="notice" style="margin-bottom:22px">交互演示：不连接模型，不执行真实工具。以下步骤、产物与回执均为模拟，不能作为执行验收证据。</div><div class="execution-layout"><aside class="panel">${state.executions.map((x,i)=>`<button class="execution-item ${i===state.selectedExecution?'active':''}" data-execution="${i}">${badge(x.status,x.status.includes('失败')?'red':x.status.includes('授权')?'orange':'blue')}<h3>${esc(x.title)}</h3><p>${x.ref} · 演示本地模型<br>关联 ${x.materials.map(id=>findTask(id)?.ref||id.replace('line','产线 ')).join(' / ')}</p></button>`).join('')}</aside><section class="panel execution-detail"><div class="row between"><small class="muted">${ex.ref}</small>${badge(ex.status,'orange')}</div><h2>${esc(ex.title)}</h2><div class="source-box"><strong>本次授权范围</strong><br>${esc(ex.scope)}<br>材料：${ex.materials.map(id=>esc(findTask(id)?.ref||id.replace('line','产线 '))).join('、')}<br>工具：只读查询、草稿整理（均为模拟） · 最大 4 步<br>成功标准：真实工具回执与可读取产物；本原型无真实回执</div><div class="filter-row"><span class="muted" style="font-size:11px">演示场景</span>${select('execution-scenario',[['normal','正常演示流程'],['scope','新增目标，暂停授权'],['partial','部分步骤失败']],ex.scenario,'选择执行演示场景')}</div><div class="timeline">${executionSteps.map((s,i)=>`<div class="timeline-item"><span class="step-number ${i<ex.step?'done':i===ex.step&&ex.running?'running':''}">${i<ex.step?icon('check'):i+1}</span><div><h4>${s}</h4><p>${i<ex.step?esc(ex.log[i]||'模拟步骤已记录'):i===ex.step&&ex.running?'正在演示此步骤…':'尚未执行'}</p>${i===2&&ex.step>2?'<code>prototype / weekly-draft.md · 虚构产物引用</code>':''}</div></div>`).join('')}</div><div class="row">${ex.running?button('停止后续步骤','stop-execution','','stop'):ex.status==='待授权'?button('查看计划并授权演示','authorize-execution','primary','shield'):ex.status==='演示已暂停 · 超出授权范围'?button('查看新增授权请求','scope-request','','shield'):['演示已取消','演示已暂停'].includes(ex.status)?button('继续原授权范围演示','resume-execution','primary','play'):button('重新创建执行','new-execution','','plus')}${ex.running?button('暂停','pause-execution','','pause'):''}</div><p class="large-text" style="font-size:10px;margin-top:16px">停止会保留已有步骤。真实产品须核实已发出的外部操作，不承诺取消后撤销全部影响。</p></section></div>`;}
function settingsPage(){return `${heading('设置','连接来源、选择模型，明确每一次数据流向。','','WORKSPACE SETTINGS')}<div class="section-head"><h2>模型与服务</h2><small class="muted">配置与能力分别验证</small></div><div class="model-grid">${[['local','本地部署模型','server','仅使用许可内网服务，协议与工具能力需实际验证。','本地 / 内网 · 待配置'],['deepseek','DeepSeek 官方 API','spark','数据会发送至外部服务，需先核实材料许可。','外部服务 · 待配置'],['newapi','New API 网关','layers','网关位置不代表模型位置，需核实最终上游。','上游未知 · 待配置']].map(([id,name,ico,desc,route])=>`<section class="panel model-card"><div class="model-logo">${icon(ico==='server'?'grid':ico)}</div><h3>${name}</h3><p>${desc}</p>${badge('连接未验证')}${badge('工具能力未验证')}<div class="task-next" style="margin-bottom:18px">${route}</div><button class="btn" data-model="${id}">${icon('settings')}查看配置</button></section>`).join('')}</div><div class="panel settings-section"><h2>来源与同步</h2><div class="settings-row"><div><h3>PingCode · 公司内网</h3><p>任务拉取与选定字段回写 · 当前仅使用演示快照</p></div>${button('查看连接边界','sync-info','small','info')}</div><div class="settings-row"><div><h3>GitLab · 公司内网</h3><p>MR 元信息只读 · 发布意见、批准和合并不在范围内</p></div>${badge('未实际接入')}</div><div class="settings-row"><div><h3>定时拉取演示开关</h3><p>正式周期待评审；原型不会发起网络请求</p></div><button class="toggle ${state.syncPaused?'':'on'}" role="switch" aria-checked="${!state.syncPaused}" aria-label="定时拉取演示开关" data-action="toggle-sync"></button></div></div><div class="panel settings-section"><h2>数据与时间</h2><div class="settings-row"><div><h3>周期与时区</h3><p>Asia/Shanghai · 周一为每周起始日 · 原型固定演示日期 2026年11月06日</p></div>${icon('calendar')}</div><div class="settings-row"><div><h3>保存与备份</h3><p>本原型仅保留内存状态，刷新即重置；未实现正式备份与恢复</p></div>${badge('正式能力待开发','orange')}</div></div>`;}
function openModal(title,content,wide=false){$('#overlay-root').innerHTML=`<div class="overlay" data-backdrop="true"><section class="modal ${wide?'wide':''}" role="dialog" aria-modal="true" aria-label="${esc(title)}"><div class="modal-header"><h2>${title}</h2><button class="icon-btn" data-action="close-overlay" aria-label="关闭对话框">${icon('close')}</button></div>${content}</section></div>`;requestAnimationFrame(()=>{$('.modal input:not([type=checkbox]):not([disabled]), .modal textarea, .modal button')?.focus();});}
let lastFocus=null;
function rememberFocus(){lastFocus=document.activeElement;}
function closeOverlay(){const wasOpen=!!$('#overlay-root').innerHTML;$('#overlay-root').innerHTML='';if(wasOpen&&lastFocus?.isConnected)lastFocus.focus();}
function detail(id){const t=findTask(id);if(!t)return;rememberFocus();$('#overlay-root').innerHTML=`<div class="overlay drawer-overlay" data-backdrop="true"><aside class="drawer" role="dialog" aria-modal="true" aria-label="${esc(t.title)}"><div class="row between"><div class="row">${sourceIcon(t)}<span class="muted" style="font-size:11px">${esc(t.ref)} / ${esc(t.project)}</span></div><button class="icon-btn" data-action="close-overlay" aria-label="关闭详情">${icon('close')}</button></div><h2>${esc(t.title)}</h2><div class="row">${taskBadge(t)}${badge(t.type,t.source==='gl'?'purple':'')} ${t.sensitive?badge('敏感 · 默认不导出','orange'):''}</div><div class="detail-actions"><button class="btn ${t.today?'':'primary'} small" data-plan="${id}">${icon('flag')}${t.today?'移出今日':'安排今日'}</button><button class="btn small" data-tomorrow="${id}">${icon('calendar')}移到明日</button><button class="btn small" data-toggle-detail="${id}">${icon('check')}${t.status==='已完成'?'重开个人行动':'完成个人行动'}</button></div>${t.status==='已完成'?'<div class="notice green">个人行动已完成。来源状态保持独立，交付与验证仍需另行核对。</div>':''}<section class="detail-section"><h3>个人安排</h3><label class="field"><span>下一步行动</span><textarea class="input" id="task-next" data-id="${id}" style="min-height:80px">${esc(t.next)}</textarea></label><div class="row between"><small class="muted">只在工作台维护，不自动回写来源</small><button class="btn small" data-save-next="${id}">保存安排</button></div><dl class="detail-grid"><dt>计划日期</dt><dd>${t.today?'今日 · 11月06日':t.plan==='tomorrow'?'明日 · 11月07日':'尚未安排'}</dd><dt>来源硬截止</dt><dd>${esc(t.due)}（与个人安排独立）</dd><dt>验证结论</dt><dd>${esc(t.validation)}</dd><dt>产线关联</dt><dd>${t.line?`产线 ${t.line} · 11月月重点 / 本周重点`:'尚未关联'}</dd></dl></section>${t.source==='gl'?`<section class="detail-section"><h3>MR 评审与提交版本</h3><div class="version-box">外部状态：<strong>${t.original}</strong> / 本人评审：<strong>${t.review}</strong><br>当前版本：<code>${t.current}</code><br>已检查版本：<code>${t.checked}</code><br>${t.current!==t.checked?'<span style="color:#b68b52">发现新提交 · 旧结论仅适用于旧版本</span>':'本次结论对应当前版本'}</div><div class="row" style="margin-top:12px">${select('detail-review-status',['待审','评审中','等待修改','待复查','已结束'].map(x=>[x,x]),t.review,'本人评审进展')}<button class="btn small" data-save-review="${id}">保存评审进展</button></div><button class="btn small" style="margin-top:12px" data-reviewed="${id}">记录已检查当前版本</button>${t.original==='Merged'?'<div class="notice" style="margin-top:12px">来源已合并，本人的旧评审结论不自动更新。请检查遗留行动。</div>':''}</section>`:''}<section class="detail-section"><h3>来源快照</h3><div class="source-box">来源：${t.source==='pc'?'PingCode · 公司内网':t.source==='gl'?'GitLab · 公司内网':'本地记录'}<br>来源状态：${esc(t.original)}<br>项目 / 编号：${esc(t.project)} / ${esc(t.ref)}<br>最后成功同步：${t.source==='pc'?esc(state.sync.pc):t.source==='gl'?esc(state.sync.gl):'不适用'}<br>来源身份：demo-instance / ${esc(t.project)} / ${t.id}（虚构）</div><div class="row" style="margin-top:13px">${t.source!=='local'?`<button class="btn small" data-source-info="${id}">${icon('link')}原始页面</button>`:''}${t.source==='pc'?`<button class="btn small" data-writeback="${id}">${icon('refresh')}准备回写</button>`:''}<button class="btn small" data-split="${id}">${icon('spark')}AI 拆解</button></div></section><section class="detail-section"><h3>记录与追溯</h3><p class="large-text" style="font-size:11px">${t.note?esc(t.note)+'<br>':''}11月06日 · 演示快照<br>个人行动、来源交付与验证结论分别记录。${t.source==='gl'?`<br>旧结论：${esc(t.oldConclusion||'需补充异常路径说明')}；适用版本 ${esc(t.oldChecked||t.checked)}。`:''}</p></section></aside></div>`;$('.drawer button')?.focus();}
function quickAdd(){rememberFocus();openModal('记下一件事',`<p class="large-text" style="margin-bottom:20px">只写标题也可以，之后再整理下一步。</p><form id="quick-form"><label class="field"><span>事项标题</span><input class="input" id="quick-title" maxlength="150" placeholder="有什么需要记下来？" required></label><label class="field"><span>主分类</span>${select('quick-category',[['personal','个人任务'],['management','管理']],state.view==='manage'?'management':'personal','主分类')}</label><div class="notice green">本地记录会进入收件箱，不会在 PingCode 或 GitLab 创建事项。</div><div class="modal-footer"><button type="button" class="btn" data-action="close-overlay">取消</button><button type="submit" class="btn primary">记入收件箱</button></div></form>`);$('#quick-title').focus();}
function splitTask(id){const t=findTask(id);rememberFocus();openModal('AI 辅助拆解',`<p class="large-text">关联 ${esc(t.ref)} · ${esc(t.title)}</p><div class="notice" style="margin:16px 0">以下是预置演示建议，未调用模型。采用后仅创建本地关联行动，不回写来源。</div>${['核对最小复现场景与边界条件','完成行动并记录过程证据','执行验证，保留结果与遗留事项'].map((s,i)=>`<label class="check-label"><input type="checkbox" class="split-choice" value="${i}" checked><span contenteditable="true" role="textbox" aria-label="编辑建议 ${i+1}">${s}</span></label>`).join('')}<div class="modal-footer"><button class="btn" data-action="close-overlay">取消</button><button class="btn primary" data-adopt="${id}">采用选中的建议</button></div>`);}
function writeback(id){const t=findTask(id);rememberFocus();openModal('预览 PingCode 回写',`<div class="row">${sourceIcon(t)}<span>${esc(t.project)} / ${t.ref}</span>${badge('模拟流程','orange')}</div><p class="large-text" style="margin-top:14px">只处理本次选中的状态与评论。个人计划、私人备注与产线关联不进入回写。</p><div class="change-preview"><div><small>来源原值（演示）</small>${esc(t.original)}</div>${icon('arrow')}<div><small>建议新值</small>${select('writeback-state',[['待开发','待开发'],['开发中','开发中'],['待测试','待测试']],t.original==='开发中'?'待测试':'开发中','建议回写状态')}</div></div><label class="field"><span>选定的进展评论（可选）</span><textarea class="input" id="writeback-comment" placeholder="仅填写希望公开到来源系统的进展">代码边界处理仍在核对，验证尚未完成。</textarea></label><label class="field"><span>演示返回场景</span>${select('writeback-scenario',[['success','回写并核实成功（模拟）'],['conflict','来源已变更，发生冲突'],['timeout','响应丢失，结果待核实']], 'success','回写演示场景')}</label><div class="form-result" id="writeback-result"></div><div class="modal-footer"><button class="btn" data-action="close-overlay">关闭</button><button class="btn primary" data-submit-writeback="${id}">模拟提交并核实</button></div>`);}
function syncInfo(){rememberFocus();openModal('来源与同步',`<div class="notice" style="margin-bottom:18px">原型未接入内网。快照与刷新结果均为演示，不验证网络、权限、证书或接口能力。</div><div class="settings-row"><div><h3>PingCode</h3><p>最后演示快照：${esc(state.sync.pc)}</p></div>${badge('拉取 / 受控回写','blue')}</div><div class="settings-row"><div><h3>GitLab</h3><p>最后演示快照：${esc(state.sync.gl)}</p></div>${badge('只读','purple')}</div><div class="row" style="margin-top:20px">${button('模拟两处刷新成功','sync','primary','refresh')}${button('模拟 GitLab 断连','sync-failure','','info')}</div><div class="notice green" style="margin-top:18px">一处断连保留原快照和个人安排，另一处刷新独立完成。未返回的事项不会被当作完成或删除。</div>`);}
function lineDetail(id){const l=lines.find(l=>l.id===id);rememberFocus();openModal(`${l.name} · 月周关联`,`${badge(l.badge,l.tone)}<dl class="detail-grid"><dt>负责人</dt><dd>${l.owner}（虚构）</dd><dt>本月预期交付</dt><dd>${l.month}</dd><dt>本周阶段结果</dt><dd>${l.week}</dd><dt>实际进展</dt><dd>${esc(state.feedback[id]||l.actual)}</dd><dt>计划节点</dt><dd>11月06日（周） / 11月30日（月）</dd><dt>反馈来源</dt><dd>${l.source} / ${l.feedback}</dd><dt>关键风险</dt><dd>${l.risk}</dd></dl>${l.task?`<div class="source-box">共享关联任务：${findTask(l.task).ref} · ${findTask(l.task).title}<br>个人行动：${findTask(l.task).status} / 来源状态：${findTask(l.task).original}<br>验证结论：${esc(findTask(l.task).validation)}</div>`:''}<div class="notice" style="margin-top:17px">阶段进展、月交付验收和本人协调行动分别判断。这里不使用主观百分比计算完成度。</div><div class="modal-footer"><button class="btn" data-feedback="${id}">记录反馈</button>${id==='A'?'<button class="btn primary" data-task="mg1">查看协调行动</button>':''}</div>`);}
function feedback(id){const l=lines.find(l=>l.id===id);rememberFocus();openModal(`记录 ${l.name} 的反馈`,`<form id="feedback-form" data-id="${id}"><label class="field"><span>负责人反馈 / 实际进展</span><textarea class="input" id="feedback-text" required>${esc(state.feedback[id]||l.actual)}</textarea></label><label class="field"><span>反馈依据</span><input class="input" id="feedback-evidence" placeholder="例如：脱敏反馈摘要 / 验证记录引用" required></label><div class="notice green">记录更新后，今日、管理与回顾读取同一份反馈；不自动确认月交付或关闭风险。</div><div class="modal-footer"><button type="button" class="btn" data-action="close-overlay">取消</button><button class="btn primary" type="submit">保存演示反馈</button></div></form>`);}
function carry(id){const l=lines.find(l=>l.id===id);rememberFocus();openModal('调整与结转',`<form id="carry-form" data-id="${id}"><p class="large-text" style="margin-bottom:18px">${l.name} · ${state.cycle==='week'?l.week:l.month}</p><div class="change-preview"><div><small>原周期 · 未完成</small>${state.cycle==='week'?'11月02日—11月08日':'2026年11月'}</div>${icon('arrow')}<div><small>新周期 · 独立计划</small>${state.cycle==='week'?'11月09日—11月15日':'2026年12月'}</div></div><label class="field"><span>结转原因 / 新安排</span><textarea id="carry-reason" class="input" required placeholder="说明原计划未完成的原因与下期安排"></textarea></label><div class="notice">原承诺与未完成事实保留，新周期不将本项计为上期成果。此处仅演示结转记录。</div><div class="modal-footer"><button class="btn primary" type="submit">建立下期演示计划</button></div></form>`);}
function modelConfig(id){const names={local:'本地部署模型',deepseek:'DeepSeek 官方 API',newapi:'New API 网关'};rememberFocus();openModal(names[id],`<div class="notice" style="margin-bottom:18px">原型不采集真实凭据，也不发起连接或模型调用。</div><label class="field"><span>配置名称</span><input class="input" value="${names[id]} · 示例"></label><label class="field"><span>服务地址（占位，不连接）</span><input class="input" placeholder="在正式接入阶段按许可地址配置"></label><label class="field"><span>模型标识</span><input class="input" placeholder="以服务实际提供的模型为准"></label><label class="field"><span>凭据引用</span><input class="input" placeholder="正式产品使用独立凭据存储" disabled></label><div class="source-box">最终数据流向：${id==='local'?'待确认的内网服务':id==='deepseek'?'外部服务；材料须经许可':'待核实网关实际路由与最终上游'}<br>文本生成：未验证 / 工具调用闭环：未验证<br>超时、预算、协议适配：待技术设计</div><div class="modal-footer">${button('模拟能力检查','model-check','primary','shield')}</div>`);}
function newExecution(instruction=''){rememberFocus();openModal('制定执行计划',`<form id="execution-form"><label class="field"><span>本次目标</span><textarea class="input" id="execution-goal" required>${esc(instruction||'汇集产线本周偏差，整理下一步跟进建议')}</textarea></label><label class="field"><span>模型配置</span>${select('execution-model',[['local','演示本地模型 · 模拟工具能力'],['deepseek','DeepSeek · 未验证，禁止内部材料执行'],['newapi','New API · 上游未知，禁止内部材料执行']],'local','执行模型')}</label><div class="field-label">允许使用的材料</div>${[['pc1','PC-1248 · 个人行动与验证状态'],['gl1','调度服务 !86 · MR 元信息（只读）'],['lineA','产线 A · 本周脱敏反馈']].map(([id,label])=>`<label class="check-label"><input class="execution-material" type="checkbox" value="${id}" checked>${label}</label>`).join('')}<div class="notice">计划仅允许读取选定材料、整理本地草稿。新增目标需要暂停确认；GitLab 写入和通用命令执行不开放。模型与工具均为演示。</div><div class="modal-footer"><button class="btn" type="button" data-action="close-overlay">取消</button><button type="submit" class="btn primary">生成演示计划</button></div></form>`,true);}
function authorizeExecution(){const ex=state.executions[state.selectedExecution];rememberFocus();openModal('确认本次计划与授权',`<h3 style="line-height:1.9">${esc(ex.title)}</h3><div class="source-box" style="margin-top:15px">工具：演示只读查询 / 演示草稿整理<br>目标：${ex.materials.map(id=>esc(findTask(id)?.ref||id)).join('、')}<br>写入范围：只生成页面内演示草稿；不回写外部系统<br>预算：最多 4 步，模型用量与费用未知<br>资料许可：仅当前虚构材料，不切换外部服务</div><ol class="large-text" style="font-size:11px">${executionSteps.map(s=>`<li>${s}</li>`).join('')}</ol><div class="notice">开始后将播放模拟步骤。没有真实工具回执，演示结束也不会标为真实任务完成。</div><div class="modal-footer">${button('返回','close-overlay')}${button('授权并开始演示','run-execution','primary','play')}</div>`);}
let runTimer=null;
function runExecution(){const ex=state.executions[state.selectedExecution];if(state.executions.some(x=>x.running))return toast('已有演示正在运行，请先停止');ex.running=true;ex.status='演示执行中';closeOverlay();render();const advance=()=>{if(!ex.running)return;if(ex.step===2&&ex.scenario==='scope'){ex.running=false;ex.status='演示已暂停 · 超出授权范围';ex.log.push('请求访问未选中的 PC-1261；已暂停，未读取新增目标');if(state.view==='executions')render();toast('发现新增目标 PC-1261，已暂停等待确认');return;}if(ex.step===2&&ex.scenario==='partial'){ex.running=false;ex.status='演示部分失败';ex.log.push('模拟产物生成失败；前两步记录已保留');if(state.view==='executions')render();toast('模拟部分失败，已保留前两步结果');return;}ex.log[ex.step]=['已读取所选虚构材料；未请求外部服务','已整理来源、进展、偏差；敏感材料排除','已构建页面内演示草稿，无真实工具产物','仅检查模拟数据；无真实回执，核验未通过'][ex.step];ex.step++;if(ex.step>=4){ex.running=false;ex.status='演示结束 · 未真实核验';toast('演示流程结束；未执行真实任务，未通过真实核验');}if(state.view==='executions')render();if(ex.running)runTimer=setTimeout(advance,1100);};runTimer=setTimeout(advance,1100);}
function stopExecution(pause=false){const ex=state.executions[state.selectedExecution];ex.running=false;clearTimeout(runTimer);ex.status=pause?'演示已暂停':'演示已取消';render();toast(`已${pause?'暂停':'停止'}后续演示，保留 ${ex.step} 步记录`);}
function toggleTask(id){const t=findTask(id);if(t.status==='已完成'){t.status=t.previousStatus||'待处理';t.note='个人行动已重开；原完成事实保留。';}else{t.previousStatus=t.status;t.status='已完成';t.note='个人行动在本次演示中完成；来源状态与验证结论未改变。';}render();toast(`个人行动${t.status==='已完成'?'已完成':'已重开'}；来源状态仍为 ${t.original}`);}
async function copyText(text){try{await navigator.clipboard.writeText(text);toast('正文已复制，保留原换行与缩进');}catch{rememberFocus();openModal('自动复制失败，请手工复制',`<p class="large-text" style="margin-bottom:15px">浏览器未允许剪贴板访问。正文保持不变，请选择后手工复制。</p><textarea class="input" id="manual-copy" readonly style="height:300px">${esc(text)}</textarea>`);$('#manual-copy').select();}}
function savePrompt(){const title=$('#prompt-title').value.trim();const body=$('#prompt-body').value;if(!title||!body.trim())return toast('请填写标题和正文，输入内容已保留');state.prompts[state.selectedPrompt]={title,body,tag:$('#prompt-tag').value.trim(),updated:'本次演示刚刚保存'};state.promptDirty=false;state.promptDraft=null;render();toast('已保存到本次演示，刷新页面会重置');}
function buildReview(){const selected=sourceMaterial().filter(m=>state.reviewSources.has(m.id));if(!selected.length)return toast('请先选择至少一项事实材料');const facts=selected.map(m=>{if(m.id.startsWith('line')){const l=lines.find(l=>`line${l.id}`===m.id);return `- [${m.ref}] ${state.feedback[l.id]||l.actual}（负责人反馈；月交付未验收）`;}const t=findTask(m.id);return `- [${t.project} / ${t.ref}] ${t.title}：个人行动${t.status}；来源状态 ${t.original}；${t.validation}。${t.source==='gl'?`当前 ${t.current} / 已检查 ${t.checked}。`:''}`;}).join('\n');state.reviewText=`# ${state.reviewPeriod==='week'?'本周回顾 · 11月02日—11月08日':'月度进展回顾 · 2026年11月（进行中）'}\n\n> 演示草稿，未调用模型；需人工复核。资料不是完整中心数据。\n\n## 成果与进展\n${facts}\n\n## 偏差与风险\n${selected.some(m=>m.id==='lineA')?'- [产线 A / 2026-11] 回归资源尚未确认，需协调测试窗口。\n':''}- 未取得真实验收记录，不将修改、部署或阶段进展计为已验证交付。\n\n## 下期计划（建议）\n- 按选中材料逐项确认下一步、责任人与计划日期。\n- 补齐验证记录和负责人反馈，复查未解决事项。\n\n## 需支持 / 待核实\n- 中心总结材料完整性待核对。\n- 以上材料来自固定演示快照，不代表当前公司系统状态。`;render();toast('已按选中事实生成演示草稿，可继续人工编辑');}
function exportReview(){const text=$('#review-draft')?.value||state.reviewText;if(!text.trim())return toast('请先生成或填写回顾草稿');const blob=new Blob([text],{type:'text/markdown;charset=utf-8'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`工作回顾-${state.reviewPeriod}-PROTOTYPE.md`;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),2000);toast('已导出当前草稿 Markdown，请复核后使用');}
const actions={
 'quick-add':quickAdd,'all-tasks':()=>{state.taskTab='all';navigate('tasks');},review:()=>navigate('review'),followups:()=>{rememberFocus();openModal('等待与跟进',followups());},
 'variant-prev':()=>cycleVariant(-1),'variant-next':()=>cycleVariant(1),state:()=>{state.showState=!state.showState;render();},'close-overlay':closeOverlay,
 'sync-info':syncInfo,sync:()=>{state.sync.pc='刚刚刷新 · 演示成功';state.sync.gl='刚刚刷新 · 演示成功';closeOverlay();render();toast('已演示两处独立刷新，个人安排保持不变');},'sync-failure':()=>{state.sync.pc='刚刚刷新 · 演示成功';state.sync.gl='演示断连失败 · 保留 08:40 快照';closeOverlay();render();toast('GitLab 模拟断连，保留快照；PingCode 演示刷新成功');},'toggle-sync':()=>{state.syncPaused=!state.syncPaused;render();toast(state.syncPaused?'定时拉取演示已暂停':'定时拉取演示已恢复；不发起网络请求');},
 'cycle-week':()=>{state.cycle='week';render();},'cycle-month':()=>{state.cycle='month';render();},'save-prompt':savePrompt,
 'new-prompt':()=>{if(!confirmPromptDiscard())return;state.prompts.push({title:'未命名提示词',tag:'',body:'',updated:'尚未保存'});state.selectedPrompt=state.prompts.length-1;state.promptDirty=true;state.promptDraft=null;render();$('#prompt-title').focus();$('#prompt-title').select();},
 'copy-prompt':()=>{const p=state.prompts[state.selectedPrompt];if(p.updated==='尚未保存')return toast('请先保存提示词');copyText(p.body);},'use-prompt':()=>{const p=state.prompts[state.selectedPrompt];if(p.updated==='尚未保存')return toast('请先保存提示词');newExecution(p.body);},
 'review-week':()=>reviewPeriod('week'),'review-month':()=>reviewPeriod('month'),'generate-review':buildReview,'copy-review':()=>{const text=$('#review-draft').value;text.trim()?copyText(text):toast('当前草稿为空');},'export-review':exportReview,
 'new-execution':()=>newExecution(),'authorize-execution':authorizeExecution,'run-execution':runExecution,'resume-execution':runExecution,'stop-execution':()=>stopExecution(),'pause-execution':()=>stopExecution(true),
 'scope-request':()=>{rememberFocus();openModal('新增目标需要单独授权',`<div class="notice">演示模型请求读取未选中的 PC-1261，超出了原材料范围。当前已暂停，未执行新增目标。</div><p class="large-text" style="margin-top:16px">原任务授权不因来源正文或模型输出自动扩展。此原型只展示请求；如需新增目标，请新建计划并明确选入材料。</p><div class="modal-footer">${button('保留暂停状态','close-overlay')}${button('新建计划','new-execution','primary')}</div>`);},
 'model-check':()=>{const el=$('.modal');let res=$('#model-check-result');if(!res){res=document.createElement('div');res.id='model-check-result';res.className='notice';el.insertBefore(res,$('.modal-footer'));}res.textContent='演示检查：没有发起连接或模型调用。连接、文本生成与工具能力均保持“未验证”。';},
 'sample-past':()=>toast('历史演示事项，用于对比本周计划；不计为本次真实交付')
};
function reviewPeriod(period){if(state.reviewPeriod===period)return;if(state.reviewText&&!confirm('切换周期会清空当前回顾草稿，是否继续？'))return;state.reviewPeriod=period;state.reviewText='';state.reviewSources=new Set(sourceMaterial().slice(0,3).map(x=>x.id));render();}
document.addEventListener('click',e=>{
 const el=e.target.closest('button,[data-task],[data-line],[data-backdrop]');if(!el)return;
 if(el.dataset.backdrop&&e.target===el){closeOverlay();return;}
 if(el.dataset.nav)return navigate(el.dataset.nav);if(el.dataset.variant)return changeVariant(el.dataset.variant);
 if(el.dataset.task)return detail(el.dataset.task);if(el.dataset.toggleTask)return toggleTask(el.dataset.toggleTask);
 if(el.dataset.toggleDetail){toggleTask(el.dataset.toggleDetail);detail(el.dataset.toggleDetail);return;}
 if(el.dataset.plan){const t=findTask(el.dataset.plan);if(t.management)return toast('管理行动保留在管理中；可在今日跟进中查看');t.today=!t.today;t.plan=t.today?'today':null;t.day=t.today?4:t.day;render();detail(t.id);toast(t.today?'已安排今日，来源截止保持不变':'已移出今日，来源截止保持不变');return;}
 if(el.dataset.tomorrow){const t=findTask(el.dataset.tomorrow);t.today=false;t.plan='tomorrow';t.day=5;render();detail(t.id);toast('已移到演示明日 11月07日，来源截止未改变');return;}
 if(el.dataset.saveNext){const t=findTask(el.dataset.saveNext);t.next=$('#task-next').value;render();detail(t.id);toast('已更新本次演示中的下一步');return;}
 if(el.dataset.saveReview){const t=findTask(el.dataset.saveReview);t.review=$('#detail-review-status').value;if(t.review==='等待修改'){t.status='等待反馈';t.next='等待作者修改，下次跟进：11月09日';}render();detail(t.id);toast('本人评审进展已记录；提交版本核对独立保留');return;}
 if(el.dataset.reviewed){const t=findTask(el.dataset.reviewed);t.oldChecked=t.checked;t.oldConclusion='原版本需补充异常路径说明';t.checked=t.current;t.review='评审中';t.validation='当前版本已检查 · 评审结论待记录';render();detail(t.id);toast('已记录当前版本，未写入 GitLab，未自动结束评审');return;}
 if(el.dataset.sourceInfo){const t=findTask(el.dataset.sourceInfo);openModal('来源原始页面',`<div class="source-box">${esc(t.project)} / ${esc(t.ref)}<br>虚构来源身份：demo-instance / ${esc(t.project)} / ${esc(t.id)}</div><div class="notice" style="margin-top:16px">未配置真实内网实例与原始链接。正式接入后在授权网络下打开来源页面。本原型不使用虚构内网链接冒充真实来源。</div>`);return;}
 if(el.dataset.writeback)return writeback(el.dataset.writeback);
 if(el.dataset.submitWriteback){const t=findTask(el.dataset.submitWriteback);const scenario=$('#writeback-scenario').value;const result=$('#writeback-result');if(scenario==='conflict'){result.innerHTML='<div class="notice red">模拟冲突：来源现值已变为“已挂起”，与预览原值不同。草稿保留，本次未覆盖来源。请重新核对变更。</div>';return;}if(scenario==='timeout'){result.innerHTML='<div class="notice">模拟响应丢失：结果待核实。草稿保留，不自动重试，不把此操作标为成功。</div>';return;}t.original=$('#writeback-state').value;t.note='本次模拟回写并核实，未连接真实来源。选定评论：'+$('#writeback-comment').value;result.innerHTML='<div class="notice green">模拟来源结果已核对。仅更新演示快照，未请求 PingCode。个人计划与验证结论保留。</div>';el.disabled=true;el.textContent='本次模拟已核实';render();toast('模拟结果已核实；未写入真实 PingCode');return;}
 if(el.dataset.split)return splitTask(el.dataset.split);
 if(el.dataset.adopt){const t=findTask(el.dataset.adopt);const selected=Array.from(document.querySelectorAll('.split-choice:checked'));if(!selected.length)return toast('请至少选择一个建议');selected.forEach((c,i)=>{state.tasks.push({id:`sub${Date.now()}${i}`,ref:`本地 · 子行动 ${state.tasks.length}`,source:'local',title:c.nextElementSibling.textContent.trim()||'待补充行动',project:t.project,type:'临时事项',status:'待处理',original:'—',today:false,day:4,next:`关联 ${t.ref} · 拆解建议待本人核对`,due:'无硬截止',validation:'尚未验证',line:t.line,management:t.management,parent:t.id,owner:'本人'});});closeOverlay();render();toast(`已采用 ${selected.length} 项本地建议，未回写来源`);return;}
 if(el.dataset.taskTab){state.taskTab=el.dataset.taskTab;state.source='all';state.type='all';state.author='all';state.mrFilter='all';render();return;}
 if(el.dataset.manageTab){state.manageTab=el.dataset.manageTab;render();return;}
 if(el.dataset.prompt){if(!confirmPromptDiscard())return;state.selectedPrompt=Number(el.dataset.prompt);state.promptDirty=false;state.promptDraft=null;render();return;}
 if(el.dataset.execution){state.selectedExecution=Number(el.dataset.execution);render();return;}
 if(el.dataset.line)return lineDetail(el.dataset.line);if(el.dataset.feedback)return feedback(el.dataset.feedback);if(el.dataset.carry)return carry(el.dataset.carry);if(el.dataset.model)return modelConfig(el.dataset.model);
 if(el.dataset.action){const action=el.dataset.action;if(action.startsWith('task:'))return detail(action.slice(5));if(action.startsWith('split:'))return splitTask(action.slice(6));actions[action]?.();}
});
document.addEventListener('submit',e=>{
 if(e.target.id==='quick-form'){e.preventDefault();const title=$('#quick-title').value.trim();if(!title)return;const management=$('#quick-category').value==='management';state.tasks.push({id:`new${Date.now()}`,ref:`本地 · ${state.tasks.length+1}`,source:'local',title,project:management?'其他管理事项':'个人安排',type:'临时事项',status:'收件箱',original:'—',today:false,day:4,next:'待整理下一步',due:'无硬截止',validation:'尚未验证',line:'',management,owner:'本人'});closeOverlay();if(!management){state.taskTab='inbox';state.taskQuery='';state.source='all';state.project='all';state.type='all';navigate('tasks');}else{state.manageTab='other';navigate('manage');}toast('已记入本次演示的收件箱');}
 if(e.target.id==='feedback-form'){e.preventDefault();const id=e.target.dataset.id;state.feedback[id]=$('#feedback-text').value.trim();const evidence=$('#feedback-evidence').value.trim();state.feedback[id]+=`（依据：${evidence}；演示记录）`;closeOverlay();render();toast('反馈已记录；风险状态与月交付结论未自动改变');}
 if(e.target.id==='carry-form'){e.preventDefault();const id=e.target.dataset.id;state.carried.push({line:`产线 ${id}`,period:state.cycle==='week'?'11月09日—11月15日':'2026年12月',reason:$('#carry-reason').value.trim()});closeOverlay();render();toast('已建立下期演示计划，原周期未完成事实保留');}
 if(e.target.id==='execution-form'){e.preventDefault();if($('#execution-model').value!=='local')return toast('此配置未验证且材料许可不足，不能用于执行内部材料');const materials=Array.from(document.querySelectorAll('.execution-material:checked')).map(x=>x.value);if(!materials.length)return toast('请选择允许使用的材料');const goal=$('#execution-goal').value.trim();if(!goal)return toast('请填写目标');state.executions.unshift({title:goal,ref:`DEMO-${String(state.executions.length+1).padStart(3,'0')}`,status:'待授权',step:0,scenario:'normal',running:false,log:[],materials,scope:'只读取选定材料；生成页面内演示草稿；不得回写公司系统'});state.selectedExecution=0;closeOverlay();navigate('executions');toast('演示计划已生成，查看范围后可单次授权');}
});
function rerenderInput(id,update){const el=$('#'+id);const pos=el?.selectionStart;update();render();const next=$('#'+id);next?.focus();if(next&&pos!==null&&pos!==undefined)next.setSelectionRange(pos,pos);}
document.addEventListener('input',e=>{
 if(e.target.id==='task-search')rerenderInput('task-search',()=>state.taskQuery=e.target.value);
 if(e.target.id==='prompt-search')rerenderInput('prompt-search',()=>state.promptQuery=e.target.value);
 if(['prompt-title','prompt-tag','prompt-body'].includes(e.target.id)){state.promptDirty=true;state.promptDraft={...state.prompts[state.selectedPrompt],title:$('#prompt-title').value,tag:$('#prompt-tag').value,body:$('#prompt-body').value};$('#prompt-save-state').textContent='有未保存修改';$('#prompt-char-count').textContent=`${$('#prompt-body').value.length} 个字符 · 复制使用最近保存的正文`;if(state.showState)renderState();}
 if(e.target.id==='review-draft')state.reviewText=e.target.value;
});
document.addEventListener('change',e=>{
 const mapping={'source-filter':'source','project-filter':'project','type-filter':'type','mr-filter':'mrFilter','author-filter':'author'};
 if(mapping[e.target.id]){state[mapping[e.target.id]]=e.target.value;render();}
 if(e.target.dataset.reviewSource){const id=e.target.dataset.reviewSource;e.target.checked?state.reviewSources.add(id):state.reviewSources.delete(id);$('#review-count').textContent=`${sourceMaterial().filter(m=>state.reviewSources.has(m.id)).length} 项已选`;}
 if(e.target.id==='execution-scenario'){const ex=state.executions[state.selectedExecution];if(ex.running){e.target.value=ex.scenario;return toast('请先暂停当前演示再调整场景');}ex.scenario=e.target.value;}
});
document.addEventListener('keydown',e=>{
 if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();$('#global-search')?.focus();return;}
 if(e.key==='Escape'){if($('#overlay-root').innerHTML)closeOverlay();else if(state.showState){state.showState=false;render();}return;}
 const dialog=$('[role=dialog]');if(dialog&&e.key==='Tab'){const nodes=Array.from(dialog.querySelectorAll('button:not([disabled]),input:not([disabled]),textarea,select,[contenteditable=true]')).filter(x=>x.offsetParent!==null);const first=nodes[0],last=nodes[nodes.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}return;}
 if(e.target.id==='global-search'&&e.key==='Enter'){state.taskQuery=e.target.value;state.taskTab='all';state.source='all';state.type='all';state.project='all';navigate('tasks');return;}
 if(e.target.matches('tr[role=button]')&&['Enter',' '].includes(e.key)){e.preventDefault();e.target.click();return;}
 if(dialog||e.target.closest('input,textarea,select,[contenteditable=true]'))return;
 if(e.key==='ArrowLeft'||e.key==='ArrowRight'){e.preventDefault();cycleVariant(e.key==='ArrowLeft'?-1:1);}
});
window.addEventListener('beforeunload',e=>{if(state.promptDirty){e.preventDefault();e.returnValue='';}});
render();
